import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
cards=json.loads((ROOT/'android/app/src/main/assets/cards.json').read_text())['cards'];index={c['id']:c for c in cards}
def py(n):return f'py-middle-{n:03}'
paths=[
('objects','Объекты, ссылки и копирование',[(2,'Сначала разделим значение и идентичность'),(3,'Теперь посмотрим, что можно менять'),(5,'Связь объектов важна при передаче аргументов'),(4,'Общее состояние проявляется в значениях по умолчанию'),(27,'Разберём копирование вложенных объектов'),(28,'Проверим повторение ссылок в матрице')]),
('async','От ожидания к конкурентным задачам',[(45,'Конкурентность и параллелизм — разные задачи'),(46,'Выберем модель выполнения'),(47,'Посмотрим, где await отдаёт управление'),(48,'Создадим отдельные задачи'),(49,'Уберём блокировку цикла событий'),(52,'Ограничим нагрузку'),(53,'Завершим задачи корректно')]),
('orders','Транзакции и надёжный заказ',[(56,'Начнём с гарантий транзакции'),(57,'Выберем нужную изоляцию'),(63,'Защитим конкурентное изменение'),(115,'Применим защиту к остатку товара'),(67,'Повтор запроса должен быть безопасен'),(55,'Соединим запись в БД и доставку задачи')]),
('orm','От ORM к быстрому запросу',[(72,'QuerySet сначала описывает будущий запрос'),(61,'Найдём проблему N+1'),(71,'Выберем способ предзагрузки'),(59,'Поймём роль индекса'),(60,'Подберём составной индекс'),(62,'Проверим фактический план')]),
('api','Контракт и защита API',[(81,'Зафиксируем семантику операции'),(82,'Согласуем ответы и ошибки'),(85,'Проверим личность и права'),(84,'Выберем хранение сессии или токена'),(86,'Защитим обработку недоверенного входа'),(87,'Отделим CORS от авторизации'),(89,'Ограничим нагрузку')]),
('delivery','Обновление и эксплуатация',[(77,'Схема базы тоже меняется'),(105,'Сохраним совместимость при обновлении'),(99,'Подготовим воспроизводимую сборку'),(100,'Отделим готовность от живости'),(101,'Учтём отдельную память процессов'),(103,'Завершим работу без потери задач')])]
chains=[]
for pid,title,steps in paths:
 chains.append(dict(id='path-'+pid,title=title,steps=[dict(card_id=py(n),connection=link) for n,link in steps]))
chains.append(dict(id='path-frameworks',title='FastAPI и безопасные миграции',steps=[dict(card_id=cid,connection=link) for cid,link in [('fastapi-001','Выберем синхронную или асинхронную границу'),('fastapi-003','Организуем время жизни сессии'),('fastapi-006','Подготовим ресурсы приложения'),('fastapi-015','Вынесем миграции из запуска worker'),('alembic-002','Укажем полное описание моделей'),('alembic-003','Проверим сгенерированный план'),('alembic-010','Согласуем схему со старой и новой версией')]]))
preferred={py(n):[py(a),py(b)] for n,a,b in [(1,6,7),(4,5,31),(6,45,46),(8,31,33),(12,21,37),(14,15,74),(15,39,41),(16,17,25),(18,78,86),(24,25,26),(31,8,109),(32,41,92),(34,37,43),(36,3,12),(37,12,38),(39,15,40),(41,75,92),(42,10,53),(50,63,115),(51,57,63),(53,42,103),(54,55,67),(64,59,60),(65,66,110),(68,69,73),(74,14,75),(77,105,70),(78,24,114),(79,67,111),(80,54,55),(83,77,105),(84,85,102),(86,85,88),(87,85,86),(88,79,102),(90,92,94),(91,92,93),(95,62,104),(96,77,94),(97,95,102),(106,13,12),(107,30,20),(108,30,21),(109,31,8),(110,65,66),(111,79,67),(112,21,20),(113,22,19),(114,23,24)]}
followups={}
for card in cards:
 related=list(preferred.get(card["id"],[]))
 for chain in chains:
  ids=[s['card_id'] for s in chain['steps']]
  if card['id'] in ids:
   pos=ids.index(card['id']);related+=ids[pos+1:]+ids[:pos]
 group=[c['id'] for c in cards if c['category_id']==card['category_id'] and c['id']!=card['id']]
 position=next(i for i,c in enumerate(cards) if c['id']==card['id'])
 related+=group[position%len(group):]+group[:position%len(group)] if group else []
 unique=list(dict.fromkeys(x for x in related if x!=card['id']))[:2]
 assert len(unique)==2
 followups[card['id']]=[dict(id=f"{card['id']}~{target}",card_id=target,question=index[target]['question'],answer=index[target]['answer'],question_audio=index[target]['question_audio']) for target in unique]
# Distinct scaffolded hints: cue, approach, complete answer; hints do not contain reference SQL.
ex=json.loads((ROOT/'android/app/src/main/assets/exercises.json').read_text())
for t in ex['sql']:
 t['hints']=[t['hint'],t['explanation']+' Сначала определите строки и связи, затем нужные столбцы и порядок результата.']
for t in ex['cases']:
 t['hints']=['Сформулируйте, какая гарантия нарушена и где находится граница операции.', 'Проверьте сначала причины и возможный сбой. Обратите внимание: '+t['mistake']]
code_hints=[
('Вспомните, копируется ли список при присваивании.','Проследите, на какой объект указывает каждое имя после append.'),
('Обратите внимание на срез.','Отдельно проследите изменение внешнего списка и исходного объекта.'),
('Когда создаётся значение аргумента по умолчанию?','Выпишите состояние этого объекта после каждого вызова.'),
('Можно ли использовать этот генератор повторно?','Отметьте, в какой строке он исчерпан.'),
('Какую переменную читают lambda?','Определите значение переменной в момент вызова, а не создания функции.'),
('Когда вычисляется аргумент по умолчанию?','Для каждой lambda отдельно зафиксируйте переданное при создании значение.'),
('Проверьте пустоту каждого объекта.','Не подменяйте истинность содержимым строкового значения.'),
('Что меняет метод, а что возвращает?','Рассмотрите состояние списка и результат вызова как разные значения.'),
('Изменился ключ или только его значение?','Проследите порядок первой вставки ключей.'),
('Сколько внутренних списков реально создано?','Нарисуйте ссылки строк матрицы на объекты.'),
('Равенство и идентичность проверяют разные свойства.','Сначала сравните содержимое, затем выясните, были ли созданы разные объекты.'),
('Обратите внимание на выход из finally.','Определите, заменяет ли он уже подготовленный результат try.'),
('Какое условие останавливает обычный zip?','Сопоставляйте элементы по позиции, пока входы дают пары.'),
('Когда any и all останавливают поиск?','Сначала отдельно определите результат каждого вызова, учитывая пустой вход.'),
('Что именно подсчитывает Counter?','Пройдите строку по символам и посчитайте указанный ключ.'),
('Копирование здесь глубокое или поверхностное?','Проверьте, разделяется ли вложенный объект между списками.')]
for task,hints in zip(ex['code'],code_hints):task['hints']=list(hints)
result=dict(chains=chains,followups=followups)
assert len(chains)==7 and all(s['card_id'] in index for c in chains for s in c['steps'])
for p in [ROOT/'data/learning_v4.json',ROOT/'android/app/src/main/assets/learning_v4.json']:p.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
for p in [ROOT/'data/exercises.json',ROOT/'android/app/src/main/assets/exercises.json']:p.write_text(json.dumps(ex,ensure_ascii=False,indent=2)+'\n')
print('7 linked routes, 310 related follow-up questions, staged hints for 39 tasks')
